wf="b669412c-7e8a-4734-846f-601525ddcfd4"
v={"customerNumber":"93075404","now":"2026-10-12T10:30:00+03:00"}
cid=None
for msg in ["Alo","Hangi kartlarım var?","İkinci kart"]:
    b={"workflowId":wf,"message":msg,"customerVariables":v}
    if cid: b["callId"]=cid
    r=freya.api("POST","/api/v2/chat/message",b); cid=r["callId"]; print(r.get("response")[:200])
c=freya.get_call(cid)
for m in c["messages"]:
    if m["role"]=="system":
        x=json.loads(m["message"])
        if x.get("event","").startswith("function") and 'balance' in json.dumps(x): print(json.dumps(x,ensure_ascii=False)[:700])
EOF

